const gmails = $input.first().json.Attendees_Gmails || '';
const emails = gmails.split(',').map(e => e.trim()).filter(e => e.length > 0);

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const invalidEmails = emails.filter(e => !emailRegex.test(e));

return [{ json: {
  ...$input.first().json,
  emails,
  totalEmailsCount: emails.length,
  validEmailsCount: emails.length - invalidEmails.length,
  invalidEmails
}}];

const raw = $input.first().json.Duration || '';
let mins = 0;
const num = parseFloat(raw);

if (raw.toLowerCase().includes('hour')) mins = Math.round(num * 60);
else if (raw.toLowerCase().includes('min')) mins = Math.round(num);

return [{ json: { ...$input.first().json, durationInMinutes: mins } }];

const items = $input.all();
const newStart = new Date($('Edit Fields').item.json.DateTime).getTime();
const dur = $('Edit Fields').item.json.durationInMinutes * 60000;
const newEnd = newStart + dur;
const buffer = 60 * 60000;

let conflict = false, conflictDetails = null;

for (const item of items) {
  if (item.json.Status === 'Cancelled') continue;
  const exStart = new Date(item.json['Date/Time']).getTime();
  const exEnd = exStart + (item.json['Duration(mins)'] || 0) * 60000;

  if (newStart < exEnd + buffer && newEnd > exStart - buffer) {
    conflict = true;
    conflictDetails = {
      title: item.json.Title,
      time: item.json['Date/Time'],
      duration: item.json['Duration(mins)']
    };
    break;
  }
}

return [{ json: { ...$('Edit Fields').item.json, conflict, conflictDetails } }];

