const now = Date.now();
return $input.all().filter(item => {
  const start = new Date(item.json['Date/Time']).getTime();
  const end = start + (item.json['Duration(mins)'] || 0) * 60000;
  return end < now;
});

const now = $now.setZone('Asia/Karachi');
const weekStart = now.startOf('week');
const weekEnd = now.endOf('week');

const rows = $input.all().filter(item => {
  const dt = DateTime.fromISO(item.json['Date/Time'], { zone: 'Asia/Karachi' });
  return dt >= weekStart && dt <= weekEnd;
});

if (rows.length === 0) {
  return [{ json: { html: 'No meetings scheduled this week.' } }];
}

const rowsHtml = rows.map(r => `
  <tr>
    <td style="border:1px solid #ddd;padding:8px">${r.json.Title}</td>
    <td style="border:1px solid #ddd;padding:8px">${DateTime.fromISO(r.json['Date/Time']).toFormat('MMM dd, h:mm a')}</td>
    <td style="border:1px solid #ddd;padding:8px">${r.json.Attendees}</td>
    <td style="border:1px solid #ddd;padding:8px">${r.json.Status}</td>
    <td style="border:1px solid #ddd;padding:8px">${r.json.Gist}</td>
  </tr>
`).join('');

const html = `
  <table style="border-collapse:collapse;font-family:sans-serif;width:100%">
    <tr>
      <th style="border:1px solid #ddd;padding:8px;background:#f2f2f2">Title</th>
      <th style="border:1px solid #ddd;padding:8px;background:#f2f2f2">Date/Time</th>
      <th style="border:1px solid #ddd;padding:8px;background:#f2f2f2">Attendees</th>
      <th style="border:1px solid #ddd;padding:8px;background:#f2f2f2">Status</th>
      <th style="border:1px solid #ddd;padding:8px;background:#f2f2f2">Gist</th>
    </tr>
    ${rowsHtml}
  </table>
`;

return [{ json: { html } }];

const cutoff = Date.now() - 30 * 24 * 60 * 60 * 1000;

return $input.all()
  .filter(item =>
    item.json.Status === 'Done' &&
    new Date(item.json['Date/Time']).getTime() < cutoff
  )
  .map(item => ({
    json: {
      ...item.json,
      ArchivedOn: new Date().toISOString(),
      row_number: item.json.row_number
    }
  }));
